INSERT INTO `dialog_training_qa` VALUES (179,1,'[主线01]开场白','喂。你好，我是办理银行贷款的客户经理，本月各大银行再次降息，已经降到了2.2厘，您最近有没有资金备用或者转贷的打算？','./uploads/tts/kb-qa/qa_179_1782263000187.wav',2,5.00,1,NULL,'flow:01',10,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(180,1,'[主线02]询问资金额度','请问您大概需要多少资金呢？','./uploads/tts/kb-qa/qa_180_1782013315087.wav',2,5.00,1,NULL,'flow:02',20,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(181,1,'[主线03]职业问询','那我这边给您匹配下产品，有几个问题需要了解一下，请问您是上班还是做生意呢？','./uploads/tts/kb-qa/qa_181_1782013301014.wav',2,5.00,1,NULL,'flow:03',30,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(182,1,'[主线04]社保公积金基础','您社保和公积金都在正常缴纳吗？','./uploads/tts/kb-qa/qa_182_1782013314444.wav',2,5.00,1,NULL,'flow:04',40,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(183,1,'[主线05]社保缴存时长','那您社保当前连续缴纳多久了？','./uploads/tts/kb-qa/qa_183_1782013312217.wav',2,5.00,1,NULL,'flow:05',50,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(184,1,'[主线06]公积金缴存时长','公积金呢！大概连续缴纳多久了呢！','./uploads/tts/kb-qa/qa_184_1782262998900.wav',2,5.00,1,NULL,'flow:06',60,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(185,1,'[主线07]月收入问询','工资呢！每月大概是多少呢！','./uploads/tts/kb-qa/qa_185_1782263000669.wav',2,5.00,1,NULL,'flow:07',70,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(186,1,'[主线08]企业开票纳税','您名下的公司有没有开票或者交税呢','./uploads/tts/kb-qa/qa_186_1782013314600.wav',2,5.00,1,NULL,'flow:08',80,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(187,1,'[主线09]年开票金额','您企业在过去一年的开票大概在多少呀','./uploads/tts/kb-qa/qa_187_1782263000051.wav',2,5.00,1,NULL,'flow:09',90,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(188,1,'[主线10]年度纳税额','纳税呢！大概有多少？','./uploads/tts/kb-qa/qa_188_1782263001088.wav',2,5.00,1,NULL,'flow:10',100,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(189,1,'[主线11]企业年流水','哦，那您公司一年流水大概多少呢？','./uploads/tts/kb-qa/qa_189_1782013314943.wav',2,5.00,1,NULL,'flow:11',110,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(190,1,'[主线12]名下车辆','嗯，那您名下有车吗？','./uploads/tts/kb-qa/qa_190_1782013316646.wav',2,5.00,1,NULL,'flow:12',120,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(191,1,'[主线13]名下房产','那再问一下啊，那您名下有房吗？','./uploads/tts/kb-qa/qa_191_1782013304491.wav',2,5.00,1,NULL,'flow:13',130,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(192,1,'[主线14]人寿保单','嗯，人寿保险购买过吗？只要投保人是你的都可以。','./uploads/tts/kb-qa/qa_192_1782262998355.wav',2,5.00,1,NULL,'flow:14',140,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(193,1,'[主线15]近三月申贷记录','好的感谢您的配合，目前呢你的基本情况已经了解完毕，再跟你核实一下你的个人信息，近三个月有申请其他银行的贷款吗','./uploads/tts/kb-qa/qa_193_1782013314741.wav',2,5.00,1,NULL,'flow:15',150,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(194,1,'[主线17]询问姓氏称呼','嗯嗯，了解了，您看咱们聊这么久了啊，还不知道怎么称呼你呢，请问您贵姓呢','./uploads/tts/kb-qa/qa_194_1782013303052.wav',2,5.00,1,NULL,'flow:17',160,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(195,1,'[主线18]转接产品经理铺垫','嗯，好的呢！您的情况这边已经记录下来了，稍后我们公司产品老师，给您致电进行详细沟通，请注意接听来电，好吧？','./uploads/tts/kb-qa/qa_195_1782013312519.wav',2,5.00,1,NULL,'flow:18',170,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(196,1,'[主线19]邀约成功结束语','好的，感谢您的配合，那其它问题后续就由专业的产品老师跟您详谈了，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_196_1782013317820.wav',2,5.00,1,NULL,'flow:19',180,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(197,1,'[主线20]意向不明兜底','是这样的，我们单位业务分工是比较明确的，也是为了更好地为您服务，我们稍后会安排产品老师来跟您直接沟通的，我这边就先不打扰您了，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_197_1782013303851.wav',2,5.00,1,NULL,'flow:20',190,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(198,1,'[主线21]邀约失败','那也没关系，稍后让我们产品老师加您微信，您留个备用，有需要随时联系，我这边就先不打扰您了，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_198_1782013317636.wav',2,5.00,1,NULL,'flow:21',200,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(199,1,'[主线22]发起添加微信','那一会我加下您的微信，请问您这个手机号是您的微信号吗？','./uploads/tts/kb-qa/qa_199_1782013294549.wav',2,5.00,1,NULL,'flow:22',210,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(200,1,'[主线23]索要微信号','那您方便说下您的微信号吗，我记一下稍后加下您呢？','./uploads/tts/kb-qa/qa_200_1782013301986.wav',2,5.00,1,NULL,'flow:23',220,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(201,1,'[主线24]加微成功结束语','好的，那我稍后添加下您，您留意一下，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_201_1782013294737.wav',2,5.00,1,NULL,'flow:24',230,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(202,1,'[主线25]意向不明加微','嗯嗯，好的，那我稍后添加下您，您留意一下，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_202_1782263000284.wav',2,5.00,1,NULL,'flow:25',240,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(203,1,'[主线26]加微失败结束语','好的。那不好意思打扰您了，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_203_1782262999514.wav',2,5.00,1,NULL,'flow:26',250,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(204,1,'[主线27]初次拒绝挽回1','啊，您别这么快拒绝嘛，现在这个贷款利息真的很低，而且呢您可以留着备用嘛！那我这边加一下微信您可以吗？','./uploads/tts/kb-qa/qa_204_1782013307137.wav',2,5.00,1,NULL,'flow:27',260,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(205,1,'[主线28]二次挽回','您可以了解一下的嘛，也可以了解一下您目前的资质情况在银行大概的可贷额度利息呢？','./uploads/tts/kb-qa/qa_205_1782013307281.wav',2,5.00,1,NULL,'flow:28',270,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(206,1,'[主线29]三次挽回','可以加你个联系方式吗。后面有需要在联系。','./uploads/tts/kb-qa/qa_206_1782013307437.wav',2,5.00,1,NULL,'flow:29',280,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(207,1,'[主线99]异常挂断兜底','抱歉，不打扰您了，再见','./uploads/tts/kb-qa/qa_207_1782013301655.wav',2,5.00,1,NULL,'flow:99',290,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(208,1,'[主线AA]客户追问产品明细转接','嗯，是这样的，因为我这边是客服专线，具体稍后让我们产品老师联系您，请您这边保持电话通畅！','./uploads/tts/kb-qa/qa_208_1782263001473.wav',2,5.00,1,NULL,'flow:AA',300,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(209,1,'1.一押|做过抵押','已经有抵押，也没有关系的，现在银行目前，针对房产已经有过抵押的可以做二次抵押，目前针对二押的贷款产品也有的呢','./uploads/tts/kb-qa/qa_209_1782013292550.wav',1,3.50,1,NULL,'fallback:1',NULL,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(210,1,'2.上不上征信|会不会上征信|查不查征信|贷款上征信|影响征信吗','这个要看具体情况，每个产品不一样，有的会上征信，有些不上征信，我们会根据您的需求来匹配产品的；这个您不用担心，只要按时还款，是不会对征信有负面影响的','./uploads/tts/kb-qa/qa_210_1782310718719.wav',1,3.50,1,NULL,'fallback:2',NULL,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(211,1,'3.上班时间','是这样的啊！我们这边的上班时间是早上9：00到下午18：00的','./uploads/tts/kb-qa/qa_211_1782013288489.wav',1,3.50,1,NULL,'fallback:3',NULL,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(212,1,'4.上门服务','只要您基本情况符合我们要求可以上门办理的','./uploads/tts/kb-qa/qa_212_1782262997979.wav',1,3.50,1,NULL,'fallback:4',NULL,'2026-06-19 14:14:26','2026-06-19 14:14:26'),(213,1,'5.不开票','您只要有流水一年能达到10万以上就可以，也可以申请办理','./uploads/tts/kb-qa/qa_213_1782262998214.wav',1,3.50,1,NULL,'fallback:5',NULL,'2026-06-19 14:14:26','2026-06-19 14:14:26'),(214,1,'6.不方便透露信息','那您看要不这样，这边稍后会安排我们产品老师再次联系您，帮您先匹配一下您的可贷额度以及利息等，请保持手机畅通！祝您生活愉快，再见','./uploads/tts/kb-qa/qa_214_1782013289111.wav',1,3.50,1,NULL,'fallback:6',NULL,'2026-06-19 14:14:26','2026-06-19 14:14:26'),(215,1,'7.个人还是企业','个人和企业都是可以做的，每种产品都有很多，针对的人群是不一样的','./uploads/tts/kb-qa/qa_215_1782013289692.wav',1,3.50,1,NULL,'fallback:7',NULL,'2026-06-19 14:14:26','2026-06-19 14:14:26'),(216,1,'8.了解利率|利息多少','可以啊，没有问题。抵押贷款利率我们这边基本上可以办理到2.2厘左右，信用贷款利率基本在2厘-6厘左右','./uploads/tts/kb-qa/qa_216_1782013293636.wav',1,3.50,1,NULL,'fallback:8',NULL,'2026-06-19 14:14:26','2026-06-19 14:14:26'),(217,1,'9.别家费用更低|别的公司便宜','是这样的，我们都是免费咨询，办理也是没有任何前期费用，而且我们能帮你匹配到，以您目前的资质条件，在所有银行能贷到的最低利息的方案，帮您大大节省了您的融资成本以及时间哦！','./uploads/tts/kb-qa/qa_217_1782262999389.wav',1,3.50,1,NULL,'fallback:9',NULL,'2026-06-19 14:14:26','2026-06-19 14:14:26'),(218,1,'10.共有房产|产证多人','这个没事的啊！这边还是有很多个人信用贷款可以申请的','./uploads/tts/kb-qa/qa_218_1782013290397.wav',1,3.50,1,NULL,'fallback:10',NULL,'2026-06-19 14:14:27','2026-06-19 14:14:27'),(219,1,'11.什么产品|有哪些贷款','可以办理的产品有很多，比如个人信用贷款，企业信用贷、房产一押、房产二押、车抵、商户贷，烟草贷，装修贷，个人消费贷，等等，我们了解您的情况后会给您匹配最合适的贷款产品，请您放心！','./uploads/tts/kb-qa/qa_219_1782013315725.wav',1,3.50,1,NULL,'fallback:11',NULL,'2026-06-19 14:14:27','2026-06-19 14:14:27'),(220,1,'12.无资产|什么都没有','如果您这边有信用卡使用半年以上，或者支付宝的芝麻信用分620分以上或者说您微信里面有微粒贷也是可以帮您操作贷款的哦！','./uploads/tts/kb-qa/qa_220_1782013291015.wav',1,3.50,1,NULL,'fallback:12',NULL,'2026-06-19 14:14:27','2026-06-19 14:14:27'),(221,1,'13.以后再说|后续考虑','那这样吧，我添加下您的微信，稍后我们微信联系，请问您这个手机号是您的微信号吗？','./uploads/tts/kb-qa/qa_221_1782013291294.wav',1,3.50,1,NULL,'fallback:13',NULL,'2026-06-19 14:14:27','2026-06-19 14:14:27'),(222,1,'14.公司优势','我这边呢！是办理银行贷款，通过率和额度是有保障的，利息最低2.2厘左右，银行直接放款，安全，快速，省心，材料也简单','./uploads/tts/kb-qa/qa_222_1782262998619.wav',1,3.50,1,NULL,'fallback:14',NULL,'2026-06-19 14:14:27','2026-06-19 14:14:27'),(223,1,'15.放款周期|多久拿钱','如果您的资金需求比较很急的话我们这边可以帮您做一个加急审批，顺利的话，最快当天就可以拿到贷款','./uploads/tts/kb-qa/qa_223_1782013298520.wav',1,3.50,1,NULL,'fallback:15',NULL,'2026-06-19 14:14:27','2026-06-19 14:14:27'),(224,1,'16.公司地址|在哪','您在哪个区呢？如果您距离我这里比较远，具体可以根据您所在地方就近安排的呢！','./uploads/tts/kb-qa/qa_224_1782013291482.wav',1,3.50,1,NULL,'fallback:16',NULL,'2026-06-19 14:14:28','2026-06-19 14:14:28'),(225,1,'17.办理方式|怎么贷','这个根据个人情况，做生意的做企业贷款，上班族可以做消费贷款，有房产的呢！也可以做抵押贷，个人信用贷，装修贷等等','./uploads/tts/kb-qa/qa_225_1782013303208.wav',1,3.50,1,NULL,'fallback:17',NULL,'2026-06-19 14:14:28','2026-06-19 14:14:28'),(226,1,'18.是否银行|中介|哪家银行|哪里|哪儿|你是谁|你是哪|哪位|什么公司|干嘛的|干什么的','我们是助贷公司！主要负责推广最新贷款产品。现在正忙着冲刺季度放款量呢！银行新推出了随借随还的备用金，利息低至2.2厘，不借的话就不产生任何利息。您可以了解一下的嘛！','./uploads/tts/kb-qa/qa_226_1782013297171.wav',1,3.50,1,NULL,'fallback:18',NULL,'2026-06-19 14:14:28','2026-06-19 14:14:28'),(227,1,'19.听不清|重复一遍','我是办理银行贷款的客户经理，本月银行再次降息，已经降到了2.2厘左右，您最近有没有资金备用或者转贷的打算','./uploads/tts/kb-qa/qa_227_1782310723787.wav',1,3.50,1,NULL,'fallback:19',NULL,'2026-06-19 14:14:28','2026-06-19 14:14:28'),(228,1,'20.隐私安全|泄露隐私','这个您放心啊！您过来预审的时候，把材料带过来就行了','./uploads/tts/kb-qa/qa_228_1782013291848.wav',1,3.50,1,NULL,'fallback:20',NULL,'2026-06-19 14:14:28','2026-06-19 14:14:28'),(229,1,'21.信号不好','喂，您好，您这边能听见么？','./uploads/tts/kb-qa/qa_229_1782310722134.wav',1,3.50,1,NULL,'fallback:21',NULL,'2026-06-19 14:14:28','2026-06-19 14:14:28'),(230,1,'22.信用卡业务','可以的呢，如果您要办理信用卡我可以帮你办理一个跟信用卡一样的随借随还的信用产品，那您这边有贷款需求么？','./uploads/tts/kb-qa/qa_230_1782013292206.wav',1,3.50,1,NULL,'fallback:22',NULL,'2026-06-19 14:14:29','2026-06-19 14:14:29'),(231,1,'23.信用贷办理条件','只要您征信良好，有稳定收入来源，即可申请办理','./uploads/tts/kb-qa/qa_231_1782013292378.wav',1,3.50,1,NULL,'fallback:23',NULL,'2026-06-19 14:14:29','2026-06-19 14:14:29'),(232,1,'24.先息后本|长年限','这个是没有问题的，咱们最长可以申请30年期的等额本息和先息后本的贷款产品呢','./uploads/tts/kb-qa/qa_232_1782013292740.wav',1,3.50,1,NULL,'fallback:24',NULL,'2026-06-19 14:14:29','2026-06-19 14:14:29'),(233,1,'25.索要详细方案','这样啊！稍后我让我们产品老师跟您联系，他会跟您说具体有哪些贷款方案','./uploads/tts/kb-qa/qa_233_1782013296983.wav',1,3.50,1,NULL,'fallback:25',NULL,'2026-06-19 14:14:29','2026-06-19 14:14:29'),(234,1,'26.公司位置发定位','稍后我加您微信给您发个定位','./uploads/tts/kb-qa/qa_234_1782262998758.wav',1,3.50,1,NULL,'fallback:26',NULL,'2026-06-19 14:14:29','2026-06-19 14:14:29'),(235,1,'27.公司名称','我是办理银行贷款，主要根据您的情况为您匹配利息低、还款灵活的贷款方案。','./uploads/tts/kb-qa/qa_235_1782013296591.wav',1,3.50,1,NULL,'fallback:27',NULL,'2026-06-19 14:14:30','2026-06-19 14:14:30'),(236,1,'28.公积金停缴|无公积金','信用贷不单纯的是针对公积金客户，即使您没有公积金，也是有很多信贷产品供您选择的呢！','./uploads/tts/kb-qa/qa_236_1782013310726.wav',1,3.50,1,NULL,'fallback:28',NULL,'2026-06-19 14:14:30','2026-06-19 14:14:30'),(237,1,'29.非贷款其他业务','我们这边主要是负责融资助贷业务，您要是有别的需求我们可以安排专人给您做详细介绍。','./uploads/tts/kb-qa/qa_237_1782013307937.wav',1,3.50,1,NULL,'fallback:29',NULL,'2026-06-19 14:14:30','2026-06-19 14:14:30'),(238,1,'30.补充资料','恩，其他资料的话，等我们的产品经老师帮您设计好贷款方案后会指导您准备的！','./uploads/tts/kb-qa/qa_238_1782263001373.wav',1,3.50,1,NULL,'fallback:30',NULL,'2026-06-19 14:14:30','2026-06-19 14:14:30'),(239,1,'31.利息偏高|过低质疑','这个利息很低的啦，一般是2-5厘，1万块钱一个月20到50块。具体要看您个人资质；目前的利息都是根据央行的基准利息来定的，抵押贷款与信用贷款会有所不同。现在贷款的利息基本也就是在2.2厘左右，一万块钱一个月也就22元的利息','./uploads/tts/kb-qa/qa_239_1782310722541.wav',1,3.50,1,NULL,'fallback:31',NULL,'2026-06-19 14:14:31','2026-06-19 14:14:31'),(240,1,'32.办理时效','产品匹配好，材料齐全，我们提交完资料，最快半个小时内可以完成放款。','./uploads/tts/kb-qa/qa_240_1782013298680.wav',1,3.50,1,NULL,'fallback:32',NULL,'2026-06-19 14:14:31','2026-06-19 14:14:31'),(241,1,'33.已在别家办理','没关系的，您可以对比一下产品做个参考，您之前是在哪个银行办的呢？','./uploads/tts/kb-qa/qa_241_1782013294361.wav',1,3.50,1,NULL,'fallback:33',NULL,'2026-06-19 14:14:31','2026-06-19 14:14:31'),(242,1,'34.单签|瞒着家人','也有产品是只要您一个人签字就可以了','./uploads/tts/kb-qa/qa_242_1782013294927.wav',1,3.50,1,NULL,'fallback:34',NULL,'2026-06-19 14:14:31','2026-06-19 14:14:31'),(243,1,'35.担心审批不下|办不成','哦，是这样的呀！线上产品是需要过系统的，对征信要求稍微偏高。但是线下很多产品是人工审核的，基本上都是可以成功放款的','./uploads/tts/kb-qa/qa_243_1782013293996.wav',1,3.50,1,NULL,'fallback:35',NULL,'2026-06-19 14:14:32','2026-06-19 14:14:32'),(244,1,'36.去哪里办理','你看这样可以吗？咋俩先加个微信，帮您先匹配一下您的可贷额度以及利息等，你看可以么！','./uploads/tts/kb-qa/qa_244_1782013295102.wav',1,3.50,1,NULL,'fallback:36',NULL,'2026-06-19 14:14:32','2026-06-19 14:14:32'),(245,1,'37.只做银行产品么','嗯，这个问题呢！我们和各大银行，还有合法持牌的金融贷款机构，国资委和省政府旗下的贷款公司我们也有合作的呢！','./uploads/tts/kb-qa/qa_245_1782013295276.wav',1,3.50,1,NULL,'fallback:37',NULL,'2026-06-19 14:14:32','2026-06-19 14:14:32'),(246,1,'38.号码来源','是这样的，我们号码都是号码段随机拨打的；我们是随机拨打的，刚好最近有好的贷款产品政策，我们就给您回访下通知下您。','./uploads/tts/kb-qa/qa_246_1782310723603.wav',1,3.50,1,NULL,'fallback:38',NULL,'2026-06-19 14:14:32','2026-06-19 14:14:32'),(247,1,'39.外地来电|号码标记诈骗','请您放心，这是我们业务号码，因为每天电话拜访比较多，号码是随机外呼的；不好意思让您误会了，这是我们业务电话，因为每天电话拜访比较多，被标记也是无可避免的','./uploads/tts/kb-qa/qa_247_1782013296026.wav',1,3.50,1,NULL,'fallback:39',NULL,'2026-06-19 14:14:32','2026-06-19 14:14:32'),(248,1,'40.合作银行','我们这边是办理银行贷款的客服经理，我们可以先加个微信，帮您先匹配产品和额度。确定好额度后，我在陪您一起再去银行签约。','./uploads/tts/kb-qa/qa_248_1782013296232.wav',1,3.50,1,NULL,'fallback:40',NULL,'2026-06-19 14:14:33','2026-06-19 14:14:33'),(249,1,'41.同行来电','抱歉，这边先不打扰您了，再见！','./uploads/tts/kb-qa/qa_249_1782013296397.wav',3,3.50,1,NULL,'fallback:41',NULL,'2026-06-19 14:14:33','2026-06-19 14:14:33'),(250,1,'42.听得到吗|能听到吗|听得见吗|在听吗|讲话能听到|能听见吗','在听的，您接着说','./uploads/tts/kb-qa/qa_250_1782310723928.wav',1,3.50,1,NULL,'fallback:42',NULL,'2026-06-19 14:14:33','2026-06-19 14:14:33'),(251,1,'43.商业贷|公积金贷区别','您说的这个应该是住房按揭贷款那一块了，当然有公积金的话，我们也是可以帮您做公积金贷款产品的。','./uploads/tts/kb-qa/qa_251_1782262998993.wav',1,3.50,1,NULL,'fallback:43',NULL,'2026-06-19 14:14:33','2026-06-19 14:14:33'),(252,1,'44.回迁房|商铺|写字楼抵押','银行对房屋性质是没有特殊要求的，只要名下有资产商品房，回迁房，房改房，单位集资房，公寓，商铺，写字楼等，都可办理。','./uploads/tts/kb-qa/qa_252_1782013297892.wav',1,3.50,1,NULL,'fallback:44',NULL,'2026-06-19 14:14:34','2026-06-19 14:14:34'),(253,1,'45.放款渠道','这个都是在银行柜台给您放款，稍后我加你微信给您对接下贷款产品，请您记得通过下我的微信哦！','./uploads/tts/kb-qa/qa_253_1782013297345.wav',1,3.50,1,NULL,'fallback:45',NULL,'2026-06-19 14:14:34','2026-06-19 14:14:34'),(254,1,'46.正在开车','那您小心开车，稍后再联系您，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_254_1782013301373.wav',1,3.50,1,NULL,'fallback:46',NULL,'2026-06-19 14:14:34','2026-06-19 14:14:34'),(255,1,'47.现在忙碌没时间','好的，那先不打扰了，我稍后加您微信一下，具体咱们就在微信上聊呗！请您记得通过下我的微信哦！','./uploads/tts/kb-qa/qa_255_1782013302187.wav',1,3.50,1,NULL,'fallback:47',NULL,'2026-06-19 14:14:34','2026-06-19 14:14:34'),(256,1,'48.备用金释义','备用金呢！就是给您申请到给到您的一笔预授信额度，随借随还，用一天算一天利息的这种产品。','./uploads/tts/kb-qa/qa_256_1782013298190.wav',1,3.50,1,NULL,'fallback:48',NULL,'2026-06-19 14:14:35','2026-06-19 14:14:35'),(257,1,'49.外地房产','一般只要位置不太偏都可以的，具体还是要跟您当面谈的','./uploads/tts/kb-qa/qa_257_1782013298366.wav',1,3.50,1,NULL,'fallback:49',NULL,'2026-06-19 14:14:35','2026-06-19 14:14:35'),(258,1,'50.征信乱|查询多|大数据花','这个情况我们也是经常遇到的，目前有部分产品对征信要求不是那么高，不同的产品符合不同的客户群体，肯定有适合你的产品方案的','./uploads/tts/kb-qa/qa_258_1782013298854.wav',1,3.50,1,NULL,'fallback:50',NULL,'2026-06-19 14:14:35','2026-06-19 14:14:35'),(259,1,'51.距离远|上班没空','关于贷款的事情目前市场还是比较混乱的，如果我们真的有这方面的需求的话，还是到实地查看一下比较稳妥，而且银行有很多款贷款产品，但是都是要本人人脸识别才能出方案的，您可以抽个半个小时先来了解一下','./uploads/tts/kb-qa/qa_259_1782262997619.wav',1,3.50,1,NULL,'fallback:51',NULL,'2026-06-19 14:14:35','2026-06-19 14:14:35'),(260,1,'52.找亲友周转','人情比钱贵，2厘多的利息已经很低了，您可以申请先做个备用，需要的时候在使用呀。','./uploads/tts/kb-qa/qa_260_1782013305469.wav',1,3.50,1,NULL,'fallback:52',NULL,'2026-06-19 14:14:36','2026-06-19 14:14:36'),(261,1,'53.资金安全','咱们这产品呢！你请放心，都是银行柜台直接放款的，利息最低才2厘多。','./uploads/tts/kb-qa/qa_261_1782013299399.wav',1,3.50,1,NULL,'fallback:53',NULL,'2026-06-19 14:14:36','2026-06-19 14:14:36'),(262,1,'54.审批通过率','这个您放心，一般都是可以贷下来的，具体金额还是要看您个人需求和资质情况来定。','./uploads/tts/kb-qa/qa_262_1782013299588.wav',1,3.50,1,NULL,'fallback:54',NULL,'2026-06-19 14:14:36','2026-06-19 14:14:36'),(263,1,'55.要求先发产品资料','嗯嗯，你看咋们俩先加个微信，我给你发产品介绍，你看可以么？','./uploads/tts/kb-qa/qa_263_1782262998506.wav',1,3.50,1,NULL,'fallback:55',NULL,'2026-06-19 14:14:36','2026-06-19 14:14:36'),(264,1,'56.家人代办贷款','可以的','./uploads/tts/kb-qa/qa_264_1782013299771.wav',1,3.50,1,NULL,'fallback:56',NULL,'2026-06-19 14:14:36','2026-06-19 14:14:36'),(265,1,'57.需要和家人商量','非常理解您，肯定是要跟家人商量的，毕竟贷款也是一件大事，那稍后我加您微信，我们微信保持联系','./uploads/tts/kb-qa/qa_265_1782013299927.wav',1,3.50,1,NULL,'fallback:57',NULL,'2026-06-19 14:14:37','2026-06-19 14:14:37'),(266,1,'58.周末能否办理','我们周末也是有工作人员值班的，只不过上班的人不多，您确定周末过来，到时我帮您提前预约好','./uploads/tts/kb-qa/qa_266_1782013310583.wav',1,3.50,1,NULL,'fallback:58',NULL,'2026-06-19 14:14:37','2026-06-19 14:14:37'),(267,1,'59.工号','我们是助贷公司的客户经理，没有工号','./uploads/tts/kb-qa/qa_267_1782013300119.wav',1,3.50,1,NULL,'fallback:59',NULL,'2026-06-19 14:14:37','2026-06-19 14:14:37'),(268,1,'60.年化利率','目前银行贷款产品，年化是在2.5%-5%之间浮动的。','./uploads/tts/kb-qa/qa_268_1782013300308.wav',1,3.50,1,NULL,'fallback:60',NULL,'2026-06-19 14:14:37','2026-06-19 14:14:37'),(269,1,'61.学生|高龄|70岁|18岁','嗯，不好意思，如果年龄超出70岁或者小于18岁，就办理不了贷款','./uploads/tts/kb-qa/qa_269_1782013316505.wav',1,3.50,1,NULL,'fallback:61',NULL,'2026-06-19 14:14:37','2026-06-19 14:14:37'),(270,1,'62.异常通话杂音','抱歉，这边先不打扰您了，再见！','./uploads/tts/kb-qa/qa_270_1782263000824.wav',1,3.50,1,NULL,'fallback:62',NULL,'2026-06-19 14:14:37','2026-06-19 14:14:37'),(271,1,'63.非银行来电疑问','我们是助贷公司，根据客户资质情况匹配合适的贷款方案。给您打的是我们客服外呼系统的号码，是随机显示的','./uploads/tts/kb-qa/qa_271_1782310724050.wav',1,3.50,1,NULL,'fallback:63',NULL,'2026-06-19 14:14:38','2026-06-19 14:14:38'),(272,1,'64.申请手续','手续是很简单的，咱们线上提交下基础材料，初审通过，咱们就可以去银行柜台办理放款了；您只需要提供您的身份证银行卡就可以申请的，稍后让我们的产品老师与您这边联系，跟您详细说一下申请细节帮助您进行申请','./uploads/tts/kb-qa/qa_272_1782013302880.wav',1,3.50,1,NULL,'fallback:64',NULL,'2026-06-19 14:14:38','2026-06-19 14:14:38'),(273,1,'65.客户经理称呼','我姓赵，或者叫我赵经理也可以',NULL,1,3.50,1,NULL,'fallback:65',NULL,'2026-06-19 14:14:38','2026-06-19 14:14:38'),(274,1,'66.还款方式','目前还款方式比较灵活，有本金利息一起还的，也有先息后本的，有随借随还的，还款方式多达上10种呢；现在这里有三种还款方式：等额本息、先息后本、后息后本，你自己选一种就行啦','./uploads/tts/kb-qa/qa_274_1782310725470.wav',1,3.50,1,NULL,'fallback:66',NULL,'2026-06-19 14:14:38','2026-06-19 14:14:38'),(275,1,'67.公司经营年限','咱们公司可是经营好多年了，经验丰富得很。尤其是融资团队，个个都是行家能手，有五年以上的经验呢，办贷款业务，绝对专业靠谱！','./uploads/tts/kb-qa/qa_275_1782263001232.wav',1,3.50,1,NULL,'fallback:67',NULL,'2026-06-19 14:14:38','2026-06-19 14:14:38'),(276,1,'68.异地无法上门','是这样的，这是我们的营销电话，您可以放心，我们全国各地级市都有合作的渠道，都是可以帮你办理的','./uploads/tts/kb-qa/qa_276_1782013288925.wav',1,3.50,1,NULL,'fallback:68',NULL,'2026-06-19 14:14:38','2026-06-19 14:14:38'),(277,1,'69.担心影响后续房贷','是这样的，如果您的贷款是在正常还款的情况下没有逾期，是不影响您房贷审批的。','./uploads/tts/kb-qa/qa_277_1782263000419.wav',1,3.50,1,NULL,'fallback:69',NULL,'2026-06-19 14:14:38','2026-06-19 14:14:38'),(278,1,'70.暂时不需要','你现在不需要也没关系，我稍等加下你的微信，以后有任何贷款方面的问题或者想了解的知识，随时都可以找我咨询，我会帮你做全面的比较和解答的。','./uploads/tts/kb-qa/qa_278_1782013289284.wav',1,3.50,1,NULL,'fallback:70',NULL,'2026-06-19 14:14:39','2026-06-19 14:14:39'),(279,1,'71.暂时不需要2','那也没关系，稍后让我们产品老师加您微信，您留个备用，有需要随时联系，我这边就先不打扰您了，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_279_1782013302534.wav',1,3.50,1,NULL,'fallback:71',NULL,'2026-06-19 14:14:39','2026-06-19 14:14:39'),(280,1,'72.农村自建房','像您这种情况也是可以办信用贷款的','./uploads/tts/kb-qa/qa_280_1782013314053.wav',1,3.50,1,NULL,'fallback:72',NULL,'2026-06-19 14:14:39','2026-06-19 14:14:39'),(281,1,'73.按揭尾款高','您的房产还有尾款的话也没有关系，现在有银行可以不结清按揭尾款的情况下直接做二押的','./uploads/tts/kb-qa/qa_281_1782013306979.wav',1,3.50,1,NULL,'fallback:73',NULL,'2026-06-19 14:14:39','2026-06-19 14:14:39'),(282,1,'74.执照注销无经营','只要您有营业执照，满一年的情况下，有收入流水，也是可以尝试办理的','./uploads/tts/kb-qa/qa_282_1782013308682.wav',1,3.50,1,NULL,'fallback:74',NULL,'2026-06-19 14:14:40','2026-06-19 14:14:40'),(283,1,'75.日常忙碌没时间','时间永远是花在做有意义的事情上面，您抽个一两个小时时间，把您所能做贷款方案都能了解到，比您每家银行跑，一个一个再作比较的情况下是不是更省时呢。','./uploads/tts/kb-qa/qa_283_1782263000979.wav',1,3.50,1,NULL,'fallback:75',NULL,'2026-06-19 14:14:40','2026-06-19 14:14:40'),(284,1,'76.无执照做经营贷','是这样的，银行针对没有营业执照的客户，只要客户有实际经营，年流水大于10万的，也有政策可以申请经营性贷款的。','./uploads/tts/kb-qa/qa_284_1782013311201.wav',1,3.50,1,NULL,'fallback:76',NULL,'2026-06-19 14:14:40','2026-06-19 14:14:40'),(285,1,'77.需要担保人','我说的贷款产品是不需要提供任何担保人的，您自己本人就可以申请了','./uploads/tts/kb-qa/qa_285_1782013306099.wav',1,3.50,1,NULL,'fallback:77',NULL,'2026-06-19 14:14:40','2026-06-19 14:14:40'),(286,1,'78.房产面积小|房龄老','目前银行对房屋面积是没有特殊要求的，名下有资产没有被查封的状态，都是可以办理的；有资产就可以申请贷款的呢，抵押贷款是不看房龄条件的','./uploads/tts/kb-qa/qa_286_1782310725970.wav',1,3.50,1,NULL,'fallback:78',NULL,'2026-06-19 14:14:40','2026-06-19 14:14:40'),(287,1,'79.抵押所需材料','房产抵押贷款的话需要，房产证，身份证，户口本，这几样基础材料即可。','./uploads/tts/kb-qa/qa_287_1782013305641.wav',1,3.50,1,NULL,'fallback:79',NULL,'2026-06-19 14:14:41','2026-06-19 14:14:41'),(288,1,'80.嫌手续繁琐','这个您不用太担心啦，现在银行办理手续都是很简单的，这样吧，稍后我加一下您微信您通过下，我把相关信息发您微信上，您先做个了解。','./uploads/tts/kb-qa/qa_288_1782013305120.wav',1,3.50,1,NULL,'fallback:80',NULL,'2026-06-19 14:14:41','2026-06-19 14:14:41'),(289,1,'81.抵押是否押房产证','银行贷款是不押客户的产证的，就跟按揭房一样，会有一个他项权证在银行，就是防止抵押过程中转移资产。','./uploads/tts/kb-qa/qa_289_1782013305957.wav',1,3.50,1,NULL,'fallback:81',NULL,'2026-06-19 14:14:41','2026-06-19 14:14:41'),(290,1,'82.前期收费|手续费','咱们都是在银行直接办理放款的，没有任何前期费用，这个您放心。','./uploads/tts/kb-qa/qa_290_1782013306258.wav',1,3.50,1,NULL,'fallback:82',NULL,'2026-06-19 14:14:41','2026-06-19 14:14:41'),(291,1,'83.初次拒绝挽留','哦，这个没事啊！那您现在有在使用信用卡分期这样的贷款或者网贷吗？现在利息比较低，可以考虑把之前的高息债务给置换一下；您可以了解一下做一个参考，如果哪天有资金需要，也可以更快办理','./uploads/tts/kb-qa/qa_291_1782310722353.wav',1,3.50,1,NULL,'fallback:83',NULL,'2026-06-19 14:14:41','2026-06-19 14:14:41'),(292,1,'84.贷款资金用途','您借出来之后，可以当备用金，后期需要周转可以直接使用，不用也是没有利息的','./uploads/tts/kb-qa/qa_292_1782013306811.wav',1,3.50,1,NULL,'fallback:84',NULL,'2026-06-19 14:14:42','2026-06-19 14:14:42'),(293,1,'85.恶意捣乱|辱骂','抱歉啊！这边先不打扰您了，再见！','./uploads/tts/kb-qa/qa_293_1782013307591.wav',3,3.50,1,NULL,'fallback:85',NULL,'2026-06-19 14:14:42','2026-06-19 14:14:42'),(294,1,'86.提前还款|违约金','这个产品是可以随借随还的，提前还款没有违约金；基本上现在银行很多产品都是按日计息的，当天结清次日就不产生利息了','./uploads/tts/kb-qa/qa_294_1782310724225.wav',1,3.50,1,NULL,'fallback:86',NULL,'2026-06-19 14:14:42','2026-06-19 14:14:42'),(295,1,'87.质疑套路贷|网贷|骗子','咋们贷款所有的合同都是和银行签订的，这个您可以放心；所有产品都是银行直接放款，利息现在最低2厘左右','./uploads/tts/kb-qa/qa_295_1782310724941.wav',1,3.50,1,NULL,'fallback:87',NULL,'2026-06-19 14:14:42','2026-06-19 14:14:42'),(296,1,'88.签约主体','我们这边只是帮您预审出方案，所有的签约流程肯定都是在银行完成的。','./uploads/tts/kb-qa/qa_296_1782013317974.wav',1,3.50,1,NULL,'fallback:88',NULL,'2026-06-19 14:14:42','2026-06-19 14:14:42'),(297,1,'89.最低申请额度','银行贷款最低申请都是五万起批，如果用不到五万的情况下，您用多少提多少，提多少产生多少利息。','./uploads/tts/kb-qa/qa_297_1782013308288.wav',1,3.50,1,NULL,'fallback:89',NULL,'2026-06-19 14:14:42','2026-06-19 14:14:42'),(298,1,'90.政策收紧|暂时不急用钱','您工作这么忙，我理解。但银行的政策都是有时效性的，您要是能抽出一个小时的时间，先把这个贷款的授信额度拿到手，那以后要用钱的时候，直接就能提款了；目前下个月银行政策可能开始收紧了，你可以先过个预审，确定额度了再说，您也可以当备用金使用','./uploads/tts/kb-qa/qa_298_1782310724431.wav',1,3.50,1,NULL,'fallback:90',NULL,'2026-06-19 14:14:43','2026-06-19 14:14:43'),(299,1,'91.最长分期年限','这个要看具体的个人情况确定，借款期限也是分很多种的，正常银行最长可以分360期，也就是分30年还款','./uploads/tts/kb-qa/qa_299_1782013300649.wav',1,3.50,1,NULL,'fallback:91',NULL,'2026-06-19 14:14:43','2026-06-19 14:14:43'),(300,1,'92.月息还是年化','我们办理的贷款年化大概在2%到5%左右，月息的话也就是1.8-4厘左右。','./uploads/tts/kb-qa/qa_300_1782013308492.wav',1,3.50,1,NULL,'fallback:92',NULL,'2026-06-19 14:14:43','2026-06-19 14:14:43'),(301,1,'93.征信差|征信不好|征信不太好|征信不怎么|征信有问题|征信记录不好|征信这块不好|黑户|逾期','目前银行有三百多种产品，不管征信好坏，都能找到适合的贷款产品。不同的产品对应不同的客户群体，上周有位客户，逾期两年忘了还贷款，咱们前两天还帮他放了63万呢','./uploads/tts/kb-qa/qa_301_1782013321720.wav',1,3.50,1,NULL,'fallback:93',NULL,'2026-06-19 14:14:43','2026-06-19 14:14:43'),(302,1,'94.服务费|中间收费|居间费','我们前期没有其他任何费用的，而且您提前还款也是没有任何违约金的。','./uploads/tts/kb-qa/qa_302_1782013308856.wav',1,3.50,1,NULL,'fallback:94',NULL,'2026-06-19 14:14:44','2026-06-19 14:14:44'),(303,1,'95.质疑机器人外呼|机器人|是不是机器人|你是机器人','怎么会呢，肯定是人工给您打电话啦。机器人的声音哪像我这样的','./uploads/tts/kb-qa/qa_303_1782013309201.wav',1,3.50,1,NULL,'fallback:95',NULL,'2026-06-19 14:14:44','2026-06-19 14:14:44'),(304,1,'96.经济纠纷涉案','可以的，现在是有针对您这类情况的专项贷款产品的。','./uploads/tts/kb-qa/qa_304_1782013309739.wav',1,3.50,1,NULL,'fallback:96',NULL,'2026-06-19 14:14:44','2026-06-19 14:14:44'),(305,1,'97.没听清|表述模糊','不好意思，刚没听清，您说什么？；真的不好意思，可能我没有理解你的意思；你看这样吧，回头让我们产品老师再跟您沟通一下，今天咱们就先这样，再见','./uploads/tts/kb-qa/qa_305_1782310724584.wav',1,3.50,1,NULL,'fallback:97',NULL,'2026-06-19 14:14:44','2026-06-19 14:14:44'),(306,1,'98.无房产证','没拿到房产证对这次贷款影响不大，办理贷款没问题','./uploads/tts/kb-qa/qa_306_1782263000560.wav',1,3.50,1,NULL,'fallback:98',NULL,'2026-06-19 14:14:45','2026-06-19 14:14:45'),(307,1,'99.无固定工作','这个也没关系的，只要你有房子或者车子或营业执照或买的寿险保单都可以做的。','./uploads/tts/kb-qa/qa_307_1782013310442.wav',1,3.50,1,NULL,'fallback:99',NULL,'2026-06-19 14:14:45','2026-06-19 14:14:45'),(308,1,'100.无抵押物','现在银行有两种贷款方式，抵押类的和纯信用的，你都可以根据自己的情况来选择。而且啊，现在信用贷款的放款量特别大，每个月都是抵押贷款的3倍呢，真的很方便！','./uploads/tts/kb-qa/qa_308_1782013310868.wav',1,3.50,1,NULL,'fallback:100',NULL,'2026-06-19 14:14:45','2026-06-19 14:14:45'),(309,1,'101.客户静默无声音|没声音|不说话','喂？；喂？在听吗？；不好意思，这边听不到您的声音，稍后安排产品老师再与您联系，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_309_1782310725800.wav',1,3.50,1,NULL,'fallback:101',NULL,'2026-06-19 14:14:45','2026-06-19 14:14:45'),(310,1,'102.无银行流水','有部分产品，只要你有收入来源也是可以申请的','./uploads/tts/kb-qa/qa_310_1782013311042.wav',1,3.50,1,NULL,'fallback:102',NULL,'2026-06-19 14:14:45','2026-06-19 14:14:45'),(311,1,'103.父母名下房产','当然可以的','./uploads/tts/kb-qa/qa_311_1782013311372.wav',1,3.50,1,NULL,'fallback:103',NULL,'2026-06-19 14:14:46','2026-06-19 14:14:46'),(312,1,'104.委婉拒绝|考虑一下再说','啊，您别这么快拒绝嘛，现在这个贷款利息真的很低，而且呢您可以留着备用嘛！那我这边加一下微信您可以吗？','./uploads/tts/kb-qa/qa_312_1782262999796.wav',1,3.50,1,NULL,'fallback:104',NULL,'2026-06-19 14:14:46','2026-06-19 14:14:46'),(313,1,'105.生病休养','那您得记得多休息哦，别太累了，身体才是革命的本钱嘛。那咱先不打扰了，下次再见啦！','./uploads/tts/kb-qa/qa_313_1782013311515.wav',1,3.50,1,NULL,'fallback:105',NULL,'2026-06-19 14:14:46','2026-06-19 14:14:46'),(314,1,'106.只授信不用款','额度都是随用随取的，您不用的话可以先放着当备用资金，不用不算利息的','./uploads/tts/kb-qa/qa_314_1782013311686.wav',1,3.50,1,NULL,'fallback:106',NULL,'2026-06-19 14:14:46','2026-06-19 14:14:46'),(315,1,'107.申请条件','材料齐全，都是当天申请，当天就可以放款','./uploads/tts/kb-qa/qa_315_1782013312044.wav',1,3.50,1,NULL,'fallback:107',NULL,'2026-06-19 14:14:47','2026-06-19 14:14:47'),(316,1,'108.办理周期','信用类贷款都是当天申请，当天放款，抵押贷款，材料齐全，最快三个工作日也是可以放款','./uploads/tts/kb-qa/qa_316_1782013294172.wav',1,3.50,1,NULL,'fallback:108',NULL,'2026-06-19 14:14:47','2026-06-19 14:14:47'),(317,1,'109.中途打断发言','您好，您是有什么问题呢？','./uploads/tts/kb-qa/qa_317_1782013305295.wav',1,3.50,1,NULL,'fallback:109',NULL,'2026-06-19 14:14:47','2026-06-19 14:14:47'),(318,1,'110.线上线下办理','线上线下都有哦，关键是看您的情况。您可以先来我们这预审一下，线上产品申请速度快，但线下产品要求相对宽松。','./uploads/tts/kb-qa/qa_318_1782013312376.wav',1,3.50,1,NULL,'fallback:110',NULL,'2026-06-19 14:14:47','2026-06-19 14:14:47'),(319,1,'111.频繁来电反感','咱们就这样碰上了，也算是有缘。就算您现在不需要，也没事儿，我们就想给您提供一个贷款的方法和策略，我加您微信，方便以后交流，行吗？','./uploads/tts/kb-qa/qa_319_1782013312836.wav',1,3.50,1,NULL,'fallback:111',NULL,'2026-06-19 14:14:47','2026-06-19 14:14:47'),(320,1,'112.需要考虑','好的，您可以先考虑一下，稍后我加下您微信可以吗？','./uploads/tts/kb-qa/qa_320_1782013313023.wav',1,3.50,1,NULL,'fallback:112',NULL,'2026-06-19 14:14:47','2026-06-19 14:14:47'),(321,1,'113.能否审批成功','现在银行有各种贷款产品，无论是信用好的还是信用不好的客户，都有适合你的方案。不同的产品对应不同的客户群体，基本上只要来申请，我们都能找到合适的产品给你','./uploads/tts/kb-qa/qa_321_1782013313322.wav',1,3.50,1,NULL,'fallback:113',NULL,'2026-06-19 14:14:48','2026-06-19 14:14:48'),(322,1,'114.辱骂脏话','抱歉，这边先不打扰您了，再见！','./uploads/tts/kb-qa/qa_322_1782013313460.wav',3,3.50,1,NULL,'fallback:114',NULL,'2026-06-19 14:14:48','2026-06-19 14:14:48'),(323,1,'115.自行去银行办理','您可以了解一下我和你说的贷款产品做个对比嘛，我们通过率和额度是有保障的，利息最低1.8厘，银行直接放款的','./uploads/tts/kb-qa/qa_323_1782013313772.wav',1,3.50,1,NULL,'fallback:115',NULL,'2026-06-19 14:14:48','2026-06-19 14:14:48'),(324,1,'116.自有渠道办理','您可以做个比较，我给你推荐的产品是很有竞争力的，利息最低1.8厘，额度30万的','./uploads/tts/kb-qa/qa_324_1782013313911.wav',1,3.50,1,NULL,'fallback:116',NULL,'2026-06-19 14:14:48','2026-06-19 14:14:48'),(325,1,'117.装修贷咨询','装修贷也是银行主打产品，他也属于信用贷的一类，只要有房产，装修贷都可以申请','./uploads/tts/kb-qa/qa_325_1782013314174.wav',1,3.50,1,NULL,'fallback:117',NULL,'2026-06-19 14:14:49','2026-06-19 14:14:49'),(326,1,'118.需要抵押吗','个人和企业的纯信用贷款是不需要任何抵押的','./uploads/tts/kb-qa/qa_326_1782013314298.wav',1,3.50,1,NULL,'fallback:118',NULL,'2026-06-19 14:14:49','2026-06-19 14:14:49'),(327,1,'119.放款需要还款吗','嗯，好的呢！您的情况这边已经记录下来了，稍后我们公司产品老师，给您致电进行详细沟通，请注意接听来电，好吧？','./uploads/tts/kb-qa/qa_327_1782263001610.wav',1,3.50,1,NULL,'fallback:119',NULL,'2026-06-19 14:14:49','2026-06-19 14:14:49'),(328,1,'120.客户要求说重点','嗯嗯，不好意思啊！就是想问一下，您近期有资金需求吗？','./uploads/tts/kb-qa/qa_328_1782013315255.wav',1,3.50,1,NULL,'fallback:120',NULL,'2026-06-19 14:14:49','2026-06-19 14:14:49'),(329,1,'121.无关闲聊调戏','非常抱歉呢，上班时间跟工作不相关的问题我们是不允许聊的，咱们还是回归到贷款上来吧。','./uploads/tts/kb-qa/qa_329_1782013315394.wav',1,3.50,1,NULL,'fallback:121',NULL,'2026-06-19 14:14:49','2026-06-19 14:14:49'),(330,1,'122.个人负债偏高','您这种情况，目前是有部分产品是不看负债的','./uploads/tts/kb-qa/qa_330_1782013315568.wav',1,3.50,1,NULL,'fallback:122',NULL,'2026-06-19 14:14:50','2026-06-19 14:14:50'),(331,1,'123.信息隐私保护|手机号怎么拿|怎么拿到我手机号|手机号哪来的','这个您大可放心，我们是专业助贷公司，对客户隐私的保护是我们最基本的职业操守，也是我们工作的重中之重。','./uploads/tts/kb-qa/qa_331_1782013320280.wav',1,3.50,1,NULL,'fallback:123',NULL,'2026-06-19 14:14:50','2026-06-19 14:14:50'),(332,1,'124.贷款年限','抵押贷款期限最长30年，信用贷款最长10年。至于还款方式，有随借随还，有先息后本，有等额本息，非常灵活','./uploads/tts/kb-qa/qa_332_1782013317261.wav',1,3.50,1,NULL,'fallback:124',NULL,'2026-06-19 14:14:50','2026-06-19 14:14:50'),(333,1,'125.贷款查征信|上征信','前期预审不会查您征信的，只有成功办理，才会查征信的。','./uploads/tts/kb-qa/qa_333_1782013309593.wav',1,3.50,1,NULL,'fallback:125',NULL,'2026-06-19 14:14:50','2026-06-19 14:14:50'),(334,1,'126.贷款所需资料','嗯，资料很简单，前期只需提供身份证和银行卡，其他资料后续会由产品老师配合您准备；资料其实挺简单的，我会先了解一下您的个人情况，然后根据产品老师给您找的贷款产品，告诉您需要准备哪些材料。','./uploads/tts/kb-qa/qa_334_1782310725268.wav',1,3.50,1,NULL,'fallback:126',NULL,'2026-06-19 14:14:51','2026-06-19 14:14:51'),(335,1,'127.贷款手续','手续是很简单的，您只要带上您的基础材料，我们这边会给您匹配3种以上方案，您确定好方案之后，咱们就可以走面签放款流程了','./uploads/tts/kb-qa/qa_335_1782013304790.wav',1,3.50,1,NULL,'fallback:127',NULL,'2026-06-19 14:14:51','2026-06-19 14:14:51'),(336,1,'128.手续费高|成本贵','我们针对优质客户每个月也会有免费的政策，这具体要看您的综合资质才能决定的','./uploads/tts/kb-qa/qa_336_1782013304962.wav',1,3.50,1,NULL,'fallback:128',NULL,'2026-06-19 14:14:51','2026-06-19 14:14:51'),(337,1,'129.自身资质优良自己办','我们自己选择适合我们的贷款产品，当然是可以的。当然，您可以在我们这里了解一下最新的贷款政策，哪个产品利率最低，额度最高，我们了解的银行产品肯定比你知道的多，可能会给你推荐利息更低的产品方案','./uploads/tts/kb-qa/qa_337_1782013313590.wav',1,3.50,1,NULL,'fallback:129',NULL,'2026-06-19 14:14:51','2026-06-19 14:14:51'),(338,1,'130.急用资金','完全可以，我们这边有产品最快当天放款，您既然这么急，不如直接带上材料来我们这边面谈一下','./uploads/tts/kb-qa/qa_338_1782013303678.wav',1,3.50,1,NULL,'fallback:130',NULL,'2026-06-19 14:14:51','2026-06-19 14:14:51'),(339,1,'131.大额资金需求','这个是没有问题的，只要你有足够的资产，我们最高是可以贷5000万的','./uploads/tts/kb-qa/qa_339_1782013315894.wav',1,3.50,1,NULL,'fallback:131',NULL,'2026-06-19 14:14:52','2026-06-19 14:14:52'),(340,1,'132.夸赞AI','非常感谢您的赞美，我们还是继续刚才那个话题吧。','./uploads/tts/kb-qa/qa_340_1782013316069.wav',1,3.50,1,NULL,'fallback:132',NULL,'2026-06-19 14:14:52','2026-06-19 14:14:52'),(341,1,'133.听不清重复三次','嗯，你看这样吧，回头让我们产品老师再跟您沟通一下，今天咱们就先这样，再见','./uploads/tts/kb-qa/qa_341_1782013310067.wav',1,3.50,1,NULL,'fallback:133',NULL,'2026-06-19 14:14:52','2026-06-19 14:14:52'),(342,1,'134.车辆抵押','可以啊，车辆可以办理信用贷和车辆抵押贷款产品，是没有问题的','./uploads/tts/kb-qa/qa_342_1782013316788.wav',1,3.50,1,NULL,'fallback:134',NULL,'2026-06-19 14:14:52','2026-06-19 14:14:52'),(343,1,'135.存量高息转贷','我们这边贷款利率最低可以做到月息1.8厘的呢！如果您之前贷款利息很高或者月供压力大，可以考虑置换的','./uploads/tts/kb-qa/qa_343_1782013319420.wav',1,3.50,1,NULL,'fallback:135',NULL,'2026-06-19 14:14:52','2026-06-19 14:14:52'),(344,1,'136.追问过多不耐烦','不好意思，也是为了给您推荐合适的产品，只有把您的条件了解清楚一点才行；极度反感的话，稍后让我们产品老师给您回电具体沟通，再见','./uploads/tts/kb-qa/qa_344_1782310725611.wav',1,3.50,1,NULL,'fallback:136',NULL,'2026-06-19 14:14:52','2026-06-19 14:14:52'),(345,1,'137.需要个贷产品','嗯，好的呢！您的情况这边已经记录下来了，稍后我们公司产品老师，给您致电进行详细沟通，请注意接听来电，好吧？','./uploads/tts/kb-qa/qa_345_1782310724769.wav',1,3.50,1,NULL,'fallback:137',NULL,'2026-06-19 14:14:53','2026-06-19 14:14:53'),(346,1,'138.非目标客群','那也没关系，稍后让我们产品老师加您微信，您留个备用，有需要随时联系，我这边就先不打扰您了，祝您生活愉快，再见！','./uploads/tts/kb-qa/qa_346_1782263002036.wav',1,3.50,1,NULL,'fallback:138',NULL,'2026-06-19 14:14:53','2026-06-19 14:14:53'),(347,1,'139.授信额度','噢！目前信用贷单笔最高额度是30万，多笔累加最高额度是300万，具体还是要看您的资质啦，确定您的情况后就能给您一个确定的额度啦！','./uploads/tts/kb-qa/qa_347_1782013320794.wav',1,3.50,1,NULL,'fallback:139',NULL,'2026-06-19 14:14:53','2026-06-19 14:14:53'),(348,1,'140.贷款安全风险','您放心，您办理的是正规的银行贷款，对您是没任何风险的。','./uploads/tts/kb-qa/qa_348_1782013320975.wav',1,3.50,1,NULL,'fallback:140',NULL,'2026-06-19 14:14:53','2026-06-19 14:14:53'),(349,1,'141.质疑高利贷','当然不是了，一般是3-5厘，1万块钱一个月30到50块；这个您放心，银行的利率不可能会高于网贷及小贷的利率的，至于您质疑的高利贷在我们这边是不会存在的。','./uploads/tts/kb-qa/qa_349_1782310725095.wav',1,3.50,1,NULL,'fallback:141',NULL,'2026-06-19 14:14:53','2026-06-19 14:14:53'),(350,1,'142.嫌办理麻烦','银行的贷款手续的确很麻烦，这也是我致电给您的原因，您在资金上有需求我可以帮您一站式解决，为您节约很多时间，不仅可以节约您的时间还能帮您省利息','./uploads/tts/kb-qa/qa_350_1782013321353.wav',1,3.50,1,NULL,'fallback:142',NULL,'2026-06-19 14:14:54','2026-06-19 14:14:54'),(351,1,'[主线30]用户没讲话，没是被到声音','不好意思啊，你这边没声音，稍后安排产品老师跟您联系吧，谢谢 再见！','./uploads/tts/kb-qa/qa_351_1781862483561.wav',2,5.00,1,NULL,'flow:30',310,'2026-06-19 17:47:43','2026-06-19 17:47:43'),(352,1,'143.还是征信|再说征信|征信就这样|一直征信|老说征信|反复说征信|还是担心征信','理解您的顾虑，征信这块我们天天遇到，不同银行门槛差别很大。线下不少方案可以人工审核，不只看征信报告。我先帮您过几个简单问题，看能匹配到哪一类产品，您看可以吗？',NULL,1,3.50,1,NULL,'fallback:143',NULL,'2026-06-26 22:09:03','2026-06-26 22:09:03'),(353,1,'144.征信花了|征信花了能办|征信查询太多|征信报告花|多头借贷','查询多、征信花这种情况我们也经常遇到，线上产品可能过不了系统，但线下有不少人工审核渠道，主要看您的资产和流水。您方便说下，主要是信用卡用得多还是近期申请比较多？我先帮您初步匹配一下',NULL,1,3.50,1,NULL,'fallback:144',NULL,'2026-06-26 22:09:03','2026-06-26 22:09:03');
