INSERT INTO `prerecord_audio_clip` VALUES (17,9,'answer','咱们综合年化最低4.2%，根据个人资质略有浮动，没有前置费用。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(18,10,'answer','额度根据您的收入和征信情况核定，一般五万到五十万，具体可以帮您测算。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(19,11,'answer','会查征信，正常按时还款对征信是正面记录，逾期才会产生不良影响。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(20,12,'answer','没有前置手续费和杂费，具体以签约合同为准。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(21,13,'answer','资料齐全的话，一般一到三个工作日可以到账，最快当天。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(22,14,'answer','身份证、银行卡就行，有公积金或社保通过率更高，线上提交很方便。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(23,15,'answer','有公积金或社保可以提额，具体额度顾问可以帮您测算。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(24,16,'answer','支持等额本息和先息后本，您可以根据资金周转选合适的方式。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(25,NULL,'buffer','我跟您说下这块。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(26,NULL,'buffer','您问的这个我清楚。',NULL,2,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(27,NULL,'buffer','简单给您讲一下。',NULL,3,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(28,NULL,'closing','除了这个，您还有其他想了解的吗？',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(29,NULL,'closing','您看还有什么要咨询的？',NULL,2,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(30,NULL,'transfer','您这个情况比较特殊，细节我这边没办法给您准确答复。我马上帮您对接专业信贷顾问，一对一给您测算讲解，您稍等片刻。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(31,NULL,'refuse','好的，理解您的想法，那就不多打扰了，祝您生活愉快。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(32,NULL,'end','好的，那不打扰您了，祝您生活愉快，再见。',NULL,1,1,'2026-06-19 14:14:25','2026-06-19 14:14:25');
