INSERT INTO `prerecord_faq` VALUES (9,'利率多少','利率多少','利率','利率,利息,年化,几个点,费率高','咱们综合年化最低4.2%，根据个人资质略有浮动，没有前置费用。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(10,'额度怎么算','额度怎么算','额度','额度,多少钱,多少万,能贷多少,批多少','额度根据您的收入和征信情况核定，一般五万到五十万，具体可以帮您测算。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(11,'上不上征信','上不上征信','征信','征信,查征信,上征信,信用记录','会查征信，正常按时还款对征信是正面记录，逾期才会产生不良影响。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(12,'有没有手续费','有没有手续费','手续费','手续费,杂费,前期费用,收费,服务费','没有前置手续费和杂费，具体以签约合同为准。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(13,'多久能放款','多久能放款','放款时效','多久,放款,到账,几天,什么时候到账','资料齐全的话，一般一到三个工作日可以到账，最快当天。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(14,'需要什么材料','需要什么材料','办理流程','材料,资料,需要什么,怎么办理,怎么办','身份证、银行卡就行，有公积金或社保通过率更高，线上提交很方便。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(15,'公积金能不能提额','公积金能不能提额','额度','公积金,提额,社保','有公积金或社保可以提额，具体额度顾问可以帮您测算。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25'),(16,'还款方式','还款方式','办理流程','还款,月供,等额,先息后本','支持等额本息和先息后本，您可以根据资金周转选合适的方式。','high_freq',0,0,0,1,'2026-06-19 14:14:25','2026-06-19 14:14:25');
